const V31SocialPatchCode = "const StorySocialRuntimeSource = \"\\n/* STORY SOCIAL RUNTIME */\\nlet StorySocialSchemaPromise = null;\\nconst StorySocialMessageTimes = new Map();\\nconst StorySocialMessageLimit = 8;\\nconst StorySocialMessageWindow = 10000;\\nconst StorySocialMessageMaxLength = 300;\\nconst StorySocialSearchMaxResults = 20;\\nconst StorySocialPresenceFreshMs = 120000;\\n\\nfunction GetStoryUserId(Username) {\\n    const Key = UsernameKey(Username);\\n    return \\\"SR-\\\" + crypto.createHash(\\\"sha256\\\").update(Key).digest(\\\"hex\\\").slice(0, 10).toUpperCase();\\n}\\n\\nfunction NormalizeStoryPresenceStatus(Value) {\\n    const Status = String(Value || \\\"\\\").trim().toLowerCase();\\n    return new Set([\\\"online\\\", \\\"idle\\\", \\\"ghost\\\"]).has(Status) ? Status : \\\"online\\\";\\n}\\n\\nfunction NormalizeStoryPresenceDuration(Value) {\\n    const Minutes = Number(Value);\\n    return [15, 30, 60].includes(Minutes) ? Minutes : 0;\\n}\\n\\nfunction EnsureStorySocialSchema() {\\n    if (!Database) return Promise.reject(new Error(\\\"DATABASE_UNAVAILABLE\\\"));\\n    if (!StorySocialSchemaPromise) {\\n        StorySocialSchemaPromise = (async () => {\\n            await Database.query(\\\"ALTER TABLE accounts ADD COLUMN IF NOT EXISTS presence_status TEXT NOT NULL DEFAULT 'online'\\\");\\n            await Database.query(\\\"ALTER TABLE accounts ADD COLUMN IF NOT EXISTS presence_until BIGINT NOT NULL DEFAULT 0\\\");\\n            await Database.query(\\\"ALTER TABLE accounts ADD COLUMN IF NOT EXISTS last_seen_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\\\");\\n            await Database.query(\\n                \\\"CREATE TABLE IF NOT EXISTS story_direct_messages (\\\" +\\n                \\\"id BIGSERIAL PRIMARY KEY,\\\" +\\n                \\\"sender_username_key TEXT NOT NULL,\\\" +\\n                \\\"recipient_username_key TEXT NOT NULL,\\\" +\\n                \\\"message TEXT NOT NULL,\\\" +\\n                \\\"created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\\\" +\\n                \\\")\\\"\\n            );\\n            await Database.query(\\n                \\\"CREATE INDEX IF NOT EXISTS story_direct_messages_pair_idx \\\" +\\n                \\\"ON story_direct_messages (sender_username_key, recipient_username_key, id DESC)\\\"\\n            );\\n            await Database.query(\\n                \\\"CREATE INDEX IF NOT EXISTS story_direct_messages_recipient_pair_idx \\\" +\\n                \\\"ON story_direct_messages (recipient_username_key, sender_username_key, id DESC)\\\"\\n            );\\n        })().catch(Error => {\\n            StorySocialSchemaPromise = null;\\n            throw Error;\\n        });\\n    }\\n    return StorySocialSchemaPromise;\\n}\\n\\nfunction GetStoryPresenceLabel(Row) {\\n    if (!Row) return \\\"offline\\\";\\n    const Status = NormalizeStoryPresenceStatus(Row.presence_status);\\n    if (Status === \\\"ghost\\\") return \\\"offline\\\";\\n\\n    const LastSeen = Row.last_seen_at ? new Date(Row.last_seen_at).getTime() : 0;\\n    if (!Number.isFinite(LastSeen) || Date.now() - LastSeen > StorySocialPresenceFreshMs) return \\\"offline\\\";\\n\\n    const Until = Number(Row.presence_until || 0);\\n    if (Until > 0 && Until <= Date.now()) return \\\"online\\\";\\n    return Status;\\n}\\n\\nfunction GetStoryPrivatePresence(Row) {\\n    const Status = NormalizeStoryPresenceStatus(Row?.presence_status);\\n    const Until = Number(Row?.presence_until || 0);\\n    return {\\n        status: Until > 0 && Until <= Date.now() ? \\\"online\\\" : Status,\\n        expiresAt: Until > Date.now() ? Until : 0\\n    };\\n}\\n\\nfunction BuildStorySocialUser(Row, ViewerKey = \\\"\\\") {\\n    const Save = NormalizeSave(Row?.save_data);\\n    const Username = String(Row?.username || \\\"\\\");\\n    const RowKey = String(Row?.username_key || UsernameKey(Username));\\n    return {\\n        userId: GetStoryUserId(Username),\\n        username: Username,\\n        isSelf: RowKey === ViewerKey,\\n        presence: GetStoryPresenceLabel(Row),\\n        stars: Object.values(Save.stars || {}).reduce((Total, Value) => Total + Number(Value || 0), 0),\\n        clearedStages: Object.values(Save.stars || {}).filter(Value => Number(Value || 0) > 0).length,\\n        deaths: Number(Save.deaths || 0),\\n        lives: Number(Save.lives || 0),\\n        maxLives: Number(Save.maxLives || 0),\\n        createdAt: Row.created_at instanceof Date ? Row.created_at.toISOString() : Row.created_at\\n    };\\n}\\n\\nfunction NormalizeStoryDirectMessage(Value) {\\n    return String(Value || \\\"\\\")\\n        .replace(/[\\\\u0000-\\\\u001F\\\\u007F]/g, \\\" \\\")\\n        .replace(/\\\\s+/g, \\\" \\\")\\n        .trim()\\n        .slice(0, StorySocialMessageMaxLength);\\n}\\n\\nfunction AllowStoryDirectMessage(Username) {\\n    const Key = UsernameKey(Username);\\n    const Now = Date.now();\\n    const Times = (StorySocialMessageTimes.get(Key) || []).filter(Time => Now - Time < StorySocialMessageWindow);\\n    if (Times.length >= StorySocialMessageLimit) {\\n        StorySocialMessageTimes.set(Key, Times);\\n        return false;\\n    }\\n    Times.push(Now);\\n    StorySocialMessageTimes.set(Key, Times);\\n    return true;\\n}\\n\\nasync function GetStorySocialRowByUsername(Username) {\\n    await EnsureStorySocialSchema();\\n    const Result = await Database.query(\\n        \\\"SELECT username_key, username, save_data, created_at, presence_status, presence_until, last_seen_at \\\" +\\n        \\\"FROM accounts WHERE username_key = $1 LIMIT 1\\\",\\n        [UsernameKey(Username)]\\n    );\\n    return Result.rowCount ? Result.rows[0] : null;\\n}\\n\\nasync function SearchStorySocialUsers(CurrentUsername, QueryValue) {\\n    await EnsureStorySocialSchema();\\n    const QueryKey = UsernameKey(String(QueryValue || \\\"\\\").trim().slice(0, 40));\\n    if (!QueryKey) return [];\\n\\n    const Pattern = QueryKey + \\\"%\\\";\\n    const Prefix = QueryKey + \\\"%\\\";\\n    const CurrentKey = UsernameKey(CurrentUsername);\\n\\n    const Result = await Database.query(\\n        \\\"SELECT username_key, username, save_data, created_at, presence_status, presence_until, last_seen_at \\\" +\\n        \\\"FROM accounts \\\" +\\n        \\\"WHERE username_key LIKE $1 \\\" +\\n        \\\"ORDER BY CASE WHEN username_key = $2 THEN 0 WHEN username_key LIKE $3 THEN 1 ELSE 2 END, username_key ASC \\\" +\\n        \\\"LIMIT $4\\\",\\n        [Pattern, CurrentKey, Prefix, StorySocialSearchMaxResults]\\n    );\\n\\n    return Result.rows.map(Row => BuildStorySocialUser(Row, CurrentKey));\\n}\\n\\nasync function LoadStoryConversation(CurrentUsername, TargetUsername, LimitValue = 50) {\\n    const Target = await GetStorySocialRowByUsername(TargetUsername);\\n    if (!Target) throw new Error(\\\"That user does not exist.\\\");\\n\\n    const CurrentKey = UsernameKey(CurrentUsername);\\n    const TargetKey = String(Target.username_key);\\n    const Limit = Math.max(1, Math.min(100, Number(LimitValue) || 50));\\n\\n    const Result = await Database.query(\\n        \\\"SELECT id, sender_username_key, recipient_username_key, message, created_at \\\" +\\n        \\\"FROM story_direct_messages \\\" +\\n        \\\"WHERE (sender_username_key = $1 AND recipient_username_key = $2) \\\" +\\n        \\\"OR (sender_username_key = $2 AND recipient_username_key = $1) \\\" +\\n        \\\"ORDER BY id DESC LIMIT $3\\\",\\n        [CurrentKey, TargetKey, Limit]\\n    );\\n\\n    return Result.rows.reverse().map(Row => ({\\n        id: String(Row.id),\\n        senderUsername: Row.sender_username_key === CurrentKey ? CurrentUsername : Target.username,\\n        recipientUsername: Row.recipient_username_key === CurrentKey ? CurrentUsername : Target.username,\\n        text: Row.message,\\n        sentAt: Row.created_at instanceof Date ? Row.created_at.toISOString() : Row.created_at\\n    }));\\n}\\n\\nasync function StoreStoryDirectMessage(SenderUsername, TargetUsername, TextValue) {\\n    await EnsureStorySocialSchema();\\n\\n    const Sender = await GetStorySocialRowByUsername(SenderUsername);\\n    const Recipient = await GetStorySocialRowByUsername(TargetUsername);\\n    if (!Sender || !Recipient) throw new Error(\\\"That user does not exist.\\\");\\n\\n    if (UsernameKey(Sender.username) === UsernameKey(Recipient.username)) {\\n        throw new Error(\\\"You cannot message yourself.\\\");\\n    }\\n\\n    const RawText = String(TextValue || \\\"\\\").trim();\\n    if (RawText.length > StorySocialMessageMaxLength) {\\n        throw new Error(\\\"Messages are limited to 300 characters.\\\");\\n    }\\n\\n    const Text = NormalizeStoryDirectMessage(RawText);\\n    if (!Text) throw new Error(\\\"Write a message first.\\\");\\n\\n    const Result = await Database.query(\\n        \\\"INSERT INTO story_direct_messages (sender_username_key, recipient_username_key, message) \\\" +\\n        \\\"VALUES ($1, $2, $3) RETURNING id, created_at\\\",\\n        [UsernameKey(Sender.username), UsernameKey(Recipient.username), Text]\\n    );\\n    const Row = Result.rows[0];\\n\\n    return {\\n        id: String(Row.id),\\n        senderUsername: Sender.username,\\n        recipientUsername: Recipient.username,\\n        text: Text,\\n        sentAt: Row.created_at instanceof Date ? Row.created_at.toISOString() : Row.created_at\\n    };\\n}\\n\\nfunction EmitStoryDirectMessage(Message) {\\n    const SenderKey = UsernameKey(Message.senderUsername);\\n    const RecipientKey = UsernameKey(Message.recipientUsername);\\n\\n    for (const Socket of Io.sockets.sockets.values()) {\\n        const SocketKey = UsernameKey(Socket.data?.username || \\\"\\\");\\n        if (SocketKey === SenderKey || SocketKey === RecipientKey) {\\n            Socket.emit(\\\"social:message\\\", Message);\\n        }\\n    }\\n}\\n\\nasync function EmitStoryPresence(Username) {\\n    try {\\n        const Row = await GetStorySocialRowByUsername(Username);\\n        const Presence = GetStoryPresenceLabel(Row);\\n\\n        for (const Socket of Io.sockets.sockets.values()) {\\n            Socket.emit(\\\"social:presence\\\", {\\n                userId: GetStoryUserId(Username),\\n                username: String(Username || \\\"\\\"),\\n                presence: Presence\\n            });\\n        }\\n    } catch (Error) {\\n        console.error(\\\"Story social presence broadcast failed\\\", Error);\\n    }\\n}\\n\\nasync function TouchStoryPresence(Username) {\\n    await EnsureStorySocialSchema();\\n    const Now = Date.now();\\n\\n    await Database.query(\\n        \\\"UPDATE accounts SET \\\" +\\n        \\\"last_seen_at = NOW(), \\\" +\\n        \\\"presence_status = CASE \\\" +\\n        \\\"WHEN presence_status = 'ghost' AND presence_until = 0 THEN 'ghost' \\\" +\\n        \\\"WHEN presence_until > $2 THEN presence_status \\\" +\\n        \\\"ELSE 'online' END, \\\" +\\n        \\\"presence_until = CASE WHEN presence_until > $2 THEN presence_until ELSE 0 END \\\" +\\n        \\\"WHERE username_key = $1\\\",\\n        [UsernameKey(Username), Now]\\n    );\\n}\\n\";\nconst StorySocialRouteSource = \"\\n    if (RequestPath === \\\"/api/social/search\\\" && Request.method === \\\"GET\\\") {\\n        const Url = new URL(Request.url, \\`http://\\${Request.headers.host || \\\"localhost\\\"}\\`);\\n        const Query = String(Url.searchParams.get(\\\"q\\\") || \\\"\\\").trim();\\n        try {\\n            const Users = await SearchStorySocialUsers(Account.username, Query);\\n            return SendJson(Response, 200, { users: Users }, Origin);\\n        } catch (Error) {\\n            console.error(\\\"Social user search failed\\\", Error);\\n            return SendJson(Response, 500, { error: \\\"Could not search users.\\\" }, Origin);\\n        }\\n    }\\n\\n    if (RequestPath === \\\"/api/social/profile\\\" && Request.method === \\\"GET\\\") {\\n        const Url = new URL(Request.url, \\`http://\\${Request.headers.host || \\\"localhost\\\"}\\`);\\n        const Username = String(Url.searchParams.get(\\\"username\\\") || \\\"\\\").trim();\\n        if (!Username) return SendJson(Response, 400, { error: \\\"Username is required.\\\" }, Origin);\\n\\n        try {\\n            const Row = await GetStorySocialRowByUsername(Username);\\n            if (!Row) return SendJson(Response, 404, { error: \\\"User not found.\\\" }, Origin);\\n            return SendJson(Response, 200, {\\n                user: BuildStorySocialUser(Row, UsernameKey(Account.username))\\n            }, Origin);\\n        } catch (Error) {\\n            console.error(\\\"Social profile lookup failed\\\", Error);\\n            return SendJson(Response, 500, { error: \\\"Could not load that user.\\\" }, Origin);\\n        }\\n    }\\n\\n    if (RequestPath === \\\"/api/social/me\\\" && Request.method === \\\"GET\\\") {\\n        try {\\n            const Row = await GetStorySocialRowByUsername(Account.username);\\n            if (!Row) return SendJson(Response, 404, { error: \\\"Account not found.\\\" }, Origin);\\n\\n            return SendJson(Response, 200, {\\n                user: BuildStorySocialUser(Row, UsernameKey(Account.username)),\\n                privatePresence: GetStoryPrivatePresence(Row)\\n            }, Origin);\\n        } catch (Error) {\\n            console.error(\\\"Social presence lookup failed\\\", Error);\\n            return SendJson(Response, 500, { error: \\\"Could not load presence settings.\\\" }, Origin);\\n        }\\n    }\\n\\n    if (RequestPath === \\\"/api/social/status\\\" && Request.method === \\\"POST\\\") {\\n        try {\\n            await EnsureStorySocialSchema();\\n            const Body = await ReadJson(Request).catch(() => ({}));\\n            const Status = NormalizeStoryPresenceStatus(Body?.status);\\n            const Duration = NormalizeStoryPresenceDuration(Body?.durationMinutes);\\n            const Until = Duration > 0 ? Date.now() + Duration * 60000 : 0;\\n\\n            await Database.query(\\n                \\\"UPDATE accounts SET presence_status = $2, presence_until = $3, last_seen_at = NOW() WHERE username_key = $1\\\",\\n                [UsernameKey(Account.username), Status, Until]\\n            );\\n\\n            const Row = await GetStorySocialRowByUsername(Account.username);\\n            await EmitStoryPresence(Account.username);\\n\\n            return SendJson(Response, 200, {\\n                user: BuildStorySocialUser(Row, UsernameKey(Account.username)),\\n                privatePresence: GetStoryPrivatePresence(Row)\\n            }, Origin);\\n        } catch (Error) {\\n            console.error(\\\"Social status update failed\\\", Error);\\n            return SendJson(Response, 500, { error: \\\"Could not update your presence.\\\" }, Origin);\\n        }\\n    }\\n\\n    if (RequestPath === \\\"/api/social/heartbeat\\\" && Request.method === \\\"POST\\\") {\\n        try {\\n            await TouchStoryPresence(Account.username);\\n            return SendJson(Response, 200, { ok: true }, Origin);\\n        } catch (Error) {\\n            console.error(\\\"Social heartbeat failed\\\", Error);\\n            return SendJson(Response, 503, { error: \\\"Presence is temporarily unavailable.\\\" }, Origin);\\n        }\\n    }\\n\\n    if (RequestPath === \\\"/api/social/messages\\\" && Request.method === \\\"GET\\\") {\\n        const Url = new URL(Request.url, \\`http://\\${Request.headers.host || \\\"localhost\\\"}\\`);\\n        const Username = String(Url.searchParams.get(\\\"username\\\") || \\\"\\\").trim();\\n        const Limit = Number(Url.searchParams.get(\\\"limit\\\") || 50);\\n        if (!Username) return SendJson(Response, 400, { error: \\\"Username is required.\\\" }, Origin);\\n\\n        try {\\n            const Messages = await LoadStoryConversation(Account.username, Username, Limit);\\n            return SendJson(Response, 200, { messages: Messages }, Origin);\\n        } catch (Error) {\\n            console.error(\\\"Social message history failed\\\", Error);\\n            return SendJson(Response, 404, { error: Error.message || \\\"Could not load chat.\\\" }, Origin);\\n        }\\n    }\\n\\n    if (RequestPath === \\\"/api/social/messages\\\" && Request.method === \\\"POST\\\") {\\n        try {\\n            if (!AllowStoryDirectMessage(Account.username)) {\\n                return SendJson(Response, 429, { error: \\\"You are sending messages too quickly.\\\" }, Origin);\\n            }\\n\\n            const Body = await ReadJson(Request).catch(() => ({}));\\n            const Username = String(Body?.username || \\\"\\\").trim();\\n            const Message = await StoreStoryDirectMessage(Account.username, Username, Body?.message);\\n            EmitStoryDirectMessage(Message);\\n            return SendJson(Response, 201, { ok: true, message: Message }, Origin);\\n        } catch (Error) {\\n            return SendJson(Response, 400, { error: Error.message || \\\"Could not send message.\\\" }, Origin);\\n        }\\n    }\\n\";\nconst StorySocialSocketSource = \"\\n    Socket.on(\\\"social:heartbeat\\\", async (Payload, Reply = () => {}) => {\\n        try {\\n            await TouchStoryPresence(Socket.data.username);\\n            await EmitStoryPresence(Socket.data.username);\\n            Reply({ ok: true });\\n        } catch (Error) {\\n            Reply({ ok: false, error: \\\"Presence is temporarily unavailable.\\\" });\\n        }\\n    });\\n\\n    Socket.on(\\\"social:message\\\", async (Payload, Reply = () => {}) => {\\n        try {\\n            if (!AllowStoryDirectMessage(Socket.data.username)) {\\n                return Reply({ ok: false, error: \\\"You are sending messages too quickly.\\\" });\\n            }\\n\\n            const TargetUsername = String(Payload?.username || \\\"\\\").trim();\\n            const Message = await StoreStoryDirectMessage(Socket.data.username, TargetUsername, Payload?.message);\\n            EmitStoryDirectMessage(Message);\\n            Reply({ ok: true, message: Message });\\n        } catch (Error) {\\n            Reply({ ok: false, error: Error.message || \\\"Could not send message.\\\" });\\n        }\\n    });\\n\\n    TouchStoryPresence(Socket.data.username).catch(Error => {\\n        console.error(\\\"Initial Story social presence update failed\\\", Error);\\n    });\\n\";\n\nif (Source.includes(\"username: Account.username,\\n        createdAt: Account.createdAt,\")\n    && !Source.includes(\"userId: GetStoryUserId(Account.username)\")) {\n    Source = Source.replace(\n        \"username: Account.username,\\n        createdAt: Account.createdAt,\",\n        \"username: Account.username,\\n        userId: GetStoryUserId(Account.username),\\n        createdAt: Account.createdAt,\"\n    );\n}\n\nif (!Source.includes(\"async function HandleApi(Request, Response, RequestPath, Origin) {\")) {\n    throw new Error(\"Story social patch failed: API function anchor\");\n}\nif (!Source.includes(\"return SendJson(Response, 404, { error: \\\"API route not found.\\\" }, Origin);\")) {\n    throw new Error(\"Story social patch failed: API fallback anchor\");\n}\n\nSource = Source.replace(\n    \"async function HandleApi(Request, Response, RequestPath, Origin) {\",\n    StorySocialRuntimeSource + \"\\n\\nasync function HandleApi(Request, Response, RequestPath, Origin) {\"\n);\n\nSource = Source.replace(\n    \"return SendJson(Response, 404, { error: \\\"API route not found.\\\" }, Origin);\",\n    StorySocialRouteSource + \"\\n\\n    return SendJson(Response, 404, { error: \\\"API route not found.\\\" }, Origin);\"\n);\n\n    Source = Source.replace(\n        '\\n});\\n\\nHttpServer.listen',\n        \"\\n\" + StorySocialSocketSource + \"\\n});\\n\\nHttpServer.listen\"\n    );\nif (!Source.includes(\"const BackendVersion = 28;\")) {\n    throw new Error(\"Story social patch failed: backend version 28 anchor\");\n}\nSource = Source.replace(\"const BackendVersion = 28;\", \"const BackendVersion = 29;\");\n\n";
